def _sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def image_url(name: str) -> str:
    return f"{CORPUS_BASE_URL}{name}.jpg"


def fetch_corpus(*, cache_dir: str | Path | None = None, fetcher: Any = None) -> dict[str, bytes]:
    """Return every pinned image (bytes keyed by BCCD name) from the cache or the raw-content host at the pinned
    commit; a cached or fetched file is refused on any byte-size or SHA-256 mismatch."""
    cache = Path(cache_dir) if cache_dir is not None else DEFAULT_CACHE_DIR
    cache.mkdir(parents=True, exist_ok=True)
    out: dict[str, bytes] = {}
    for name, size, digest, *_rest in SAMPLE_IMAGES:
        local = cache / f"{name}.jpg"
        data = local.read_bytes() if local.is_file() else b""
        if len(data) != size or _sha256_bytes(data) != digest:
            url = image_url(name)
            if fetcher is not None:
                data = fetcher(url)
            else:
                request = urllib.request.Request(url, headers={"User-Agent": "grounding-dino-detection-pipeline"})
                with urllib.request.urlopen(request, timeout=60) as response:  # noqa: S310 - pinned https URL, digest-checked
                    data = response.read()
            if len(data) != size:
                raise ValueError(f"{name}: {len(data)} bytes, pinned {size}")
            got = _sha256_bytes(data)
            if got != digest:
                raise ValueError(f"{name}: sha256 {got} != pinned {digest}")
            local.write_bytes(data)
        out[name] = data
    return out


def _parse_objects(text: str) -> tuple[list[list[float]], list[str]]:
    boxes, labels = [], []
    for item in text.split(";"):
        cls, x0, y0, x1, y1 = item.split()
        boxes.append([float(x0), float(y0), float(x1), float(y1)])
        labels.append(CLASS_PHRASES[cls])
    return boxes, labels


def read_corpus(files: Mapping[str, bytes]) -> list[dict[str, Any]]:
    """Decode the verified images into one record per image with its boxes and phrases."""
    out = []
    for name, _size, _digest, width, height, objects in SAMPLE_IMAGES:
        if name not in files:
            continue
        image = Image.open(io.BytesIO(files[name]))
        image.load()
        if image.size != (width, height):
            raise ValueError(f"{name}: decoded size {image.size} != pinned {(width, height)}")
        boxes, labels = _parse_objects(objects)
        out.append({"id": f"bccd-{name}", "image": image.convert("RGB"), "boxes": boxes, "labels": labels, "source": f"{CORPUS_REPO}@{CORPUS_COMMIT[:12]}"})
    return out


def build_sample_dataset(
    records: Sequence[Mapping[str, Any]], *, seed: int = SAMPLE_SEED, sizes: Mapping[str, int] | None = None
) -> dict[str, list[dict[str, Any]]]:
    """Seeded image-level draw: shuffle the records and cut `sizes` (train / validation / test) in order."""
    sizes = dict(sizes or SAMPLE_SPLIT)
    pool = [dict(r) for r in records]
    random.Random(seed).shuffle(pool)
    needed = sum(sizes.values())
    if len(pool) < needed:
        raise ValueError(f"only {len(pool)} records available, need {needed}")
    out, cursor = {}, 0
    for name, count in sizes.items():
        out[name] = pool[cursor : cursor + count]
        cursor += count
    return out


def fetch_sample_dataset(*, cache_dir: str | Path | None = None, seed: int = SAMPLE_SEED) -> dict[str, list[dict[str, Any]]]:
    return build_sample_dataset(read_corpus(fetch_corpus(cache_dir=cache_dir)), seed=seed)


def check_prompts(prompts: Sequence[str]) -> list[str]:
    """The vocabulary a dataset's labels are drawn from: 1..MAX_PROMPTS distinct phrases that `format_prompts`
    accepts, returned cleaned (lowercase, no trailing period)."""
    format_prompts(prompts)
    cleaned = [p.strip().rstrip(".").strip().lower() for p in prompts]
    if len(set(cleaned)) != len(cleaned):
        raise ValueError("prompts must be distinct phrases")
    return cleaned


def _open(image: Any, where: str) -> Image.Image:
    if isinstance(image, str | Path):
        path = Path(image)
        if not path.is_file():
            raise ValueError(f"{where}: image file not found: {path}")
        image = Image.open(path)
        image.load()
    if not isinstance(image, Image.Image):
        raise ValueError(f"{where}: must be a PIL.Image.Image or a file path")
    return image


def _check_record(record: Any, index: int, vocabulary: Sequence[str]) -> dict[str, Any]:
    where = f"records[{index}]"
    if not isinstance(record, Mapping):
        raise ValueError(f"{where} must be a mapping with id/image/boxes/labels")
    for key in ("id", "image", "boxes", "labels"):
        if key not in record:
            raise ValueError(f"{where} is missing {key!r}")
    rid = record["id"]
    if not isinstance(rid, str) or not _ID_RE.match(rid):
        raise ValueError(f"{where}: id must match {_ID_RE.pattern}")
    try:
        image = validate_image(_open(record["image"], f"{where}.image"))
    except TypeError as exc:
        raise ValueError(f"{where}: {exc}") from exc
    boxes, labels = record["boxes"], record["labels"]
    if isinstance(boxes, str) or not isinstance(boxes, Sequence) or isinstance(labels, str) or not isinstance(labels, Sequence):
        raise ValueError(f"{where}: boxes and labels must be sequences")
    if len(boxes) != len(labels):
        raise ValueError(f"{where}: {len(boxes)} boxes for {len(labels)} labels")
    if not 1 <= len(boxes) <= MAX_BOXES:
        raise ValueError(f"{where}: {len(boxes)} boxes; 1..MAX_BOXES ({MAX_BOXES}) are required")
    clean_boxes, clean_labels = [], []
    for k, (box, label) in enumerate(zip(boxes, labels, strict=True)):
        try:
            x0, y0, x1, y1 = (float(v) for v in box)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"{where}: boxes[{k}] must be [x0, y0, x1, y1]") from exc
        if not (0 <= x0 < x1 <= image.width and 0 <= y0 < y1 <= image.height):
            raise ValueError(f"{where}: boxes[{k}] {list(box)} is not a non-empty box inside the {image.width}x{image.height} image")
        if not isinstance(label, str):
            raise ValueError(f"{where}: labels[{k}] must be a phrase")
        phrase = label.strip().rstrip(".").strip().lower()
        if phrase not in vocabulary:
            raise ValueError(f"{where}: labels[{k}] {label!r} is not in the prompt vocabulary {list(vocabulary)}")
        clean_boxes.append([x0, y0, x1, y1])
        clean_labels.append(phrase)
    item = {"id": rid, "image": image, "boxes": clean_boxes, "labels": clean_labels}
    for key in ("source",):
        if key in record:
            item[key] = record[key]
    return item


def validate_dataset(
    records: Sequence[Mapping[str, Any]], prompts: Sequence[str], *, min_records: int = MIN_RECORDS, max_records: int = MAX_RECORDS
) -> dict[str, Any]:
    """Structural validation of a detection dataset against its prompt vocabulary; raises ValueError before any
    model import."""
    vocabulary = check_prompts(prompts)
    if isinstance(records, Mapping) or not isinstance(records, Sequence) or isinstance(records, str | bytes):
        raise ValueError("records must be a list of {id, image, boxes, labels} mappings")
    if not min_records <= len(records) <= max_records:
        raise ValueError(f"{len(records)} records; {min_records}..{max_records} are required")
    checked, ids, counts = [], set(), dict.fromkeys(vocabulary, 0)
    for index, record in enumerate(records):
        item = _check_record(record, index, vocabulary)
        if item["id"] in ids:
            raise ValueError(f"duplicate id {item['id']!r}")
        ids.add(item["id"])
        for label in item["labels"]:
            counts[label] += 1
        checked.append(item)
    sides = [max(r["image"].size) for r in checked]
    per_image = [len(r["boxes"]) for r in checked]
    return {
        "records": checked,
        "prompts": vocabulary,
        "n_records": len(checked),
        "n_boxes": sum(per_image),
        "label_counts": counts,
        "boxes_per_image": {"min": min(per_image), "max": max(per_image)},
        "image_side": {"min": min(sides), "max": max(sides)},
        "digest": dataset_digest(checked),
        "model_id": MODEL_ID,
    }


def image_digest(image: Image.Image) -> str:
    """SHA-256 of the decoded RGB pixels (size-prefixed) — the identity a split is made disjoint on."""
    rgb = image.convert("RGB")
    return _sha256_bytes(f"{rgb.width}x{rgb.height}:".encode() + rgb.tobytes())


def dataset_digest(records: Sequence[Mapping[str, Any]]) -> str:
    """Order-independent SHA-256 over every record's id, image pixels, boxes and labels."""
    rows = []
    for r in records:
        objects = sorted((label, [round(v, 2) for v in box]) for box, label in zip(r["boxes"], r["labels"], strict=True))
        rows.append(json.dumps([r["id"], image_digest(r["image"]), objects], separators=(",", ":")))
    return _sha256_bytes("\n".join(sorted(rows)).encode("utf-8"))


def check_split_disjoint(splits: Mapping[str, Sequence[Mapping[str, Any]]]) -> dict[str, Any]:
    """Assert no image (by decoded-pixel digest) appears in two splits; returns the split sizes."""
    seen: dict[str, str] = {}
    for name, part in splits.items():
        for r in part:
            key = image_digest(r["image"])
            if key in seen and seen[key] != name:
                raise ValueError(f"image {r['id']!r} appears in both {seen[key]!r} and {name!r}")
            seen[key] = name
    return {name: len(part) for name, part in splits.items()}


def split_dataset(
    records: Sequence[Mapping[str, Any]], prompts: Sequence[str], *, val_fraction: float = 0.15, test_fraction: float = 0.2, seed: int = 0
) -> dict[str, list[dict[str, Any]]]:
    """Seeded shuffle of a BYOD dataset into train/validation/test after de-duplicating images."""
    if not (0.0 <= val_fraction < 1.0 and 0.0 < test_fraction < 1.0 and val_fraction + test_fraction < 1.0):
        raise ValueError("fractions must satisfy 0 <= val < 1, 0 < test < 1, val + test < 1")
    checked = validate_dataset(records, prompts)["records"]
    seen: set[str] = set()
    unique = []
    for record in checked:
        key = image_digest(record["image"])
        if key not in seen:
            seen.add(key)
            unique.append(record)
    random.Random(seed).shuffle(unique)
    n = len(unique)
    n_test = max(1, round(n * test_fraction))
    n_val = round(n * val_fraction)
    if n - n_test - n_val < 1:
        raise ValueError(f"{n} distinct images are too few to split into train/validation/test")
    return {"test": unique[:n_test], "validation": unique[n_test : n_test + n_val], "train": unique[n_test + n_val :]}


def load_byod_dataset(path: str | Path) -> tuple[list[dict[str, Any]], list[str]]:
    """Records and the prompt vocabulary from a directory or zip holding image files plus one `boxes.csv` with the
    columns `file`, `x0`, `y0`, `x1`, `y1`, `phrase` (one row per box); the vocabulary is the distinct phrases in
    the order they first appear."""
    source = Path(path)
    members: dict[str, bytes] = {}
    if source.is_dir():
        for file in sorted(source.rglob("*")):
            if file.is_file():
                members[file.name] = file.read_bytes()
    elif zipfile.is_zipfile(source):
        with zipfile.ZipFile(source) as archive:
            for info in archive.infolist():
                if not info.is_dir():
                    members[Path(info.filename).name] = archive.read(info)  # flattened; no extractall
    else:
        raise ValueError(f"{source} is neither a directory nor a zip file")
    if "boxes.csv" not in members:
        raise ValueError("BYOD needs a boxes.csv beside the images")
    by_file: dict[str, dict[str, Any]] = {}
    vocabulary: list[str] = []
    for row in csv.DictReader(io.StringIO(members["boxes.csv"].decode("utf-8-sig"))):
        name = str(row.get("file", "")).strip()
        if name not in members:
            raise ValueError(f"boxes.csv names {name!r}, which is not among the uploaded files")
        if name not in by_file:
            try:
                image = Image.open(io.BytesIO(members[name]))
                image.load()
            except Exception as exc:  # noqa: BLE001
                raise ValueError(f"BYOD file is not a decodable image: {name}") from exc
            by_file[name] = {"id": re.sub(r"[^A-Za-z0-9_.:-]", "_", Path(name).stem)[:64], "image": image.convert("RGB"), "boxes": [], "labels": []}
        phrase = str(row.get("phrase", "")).strip().rstrip(".").strip().lower()
        if not phrase:
            raise ValueError(f"boxes.csv row for {name!r} has no phrase")
        if phrase not in vocabulary:
            vocabulary.append(phrase)
        by_file[name]["boxes"].append([float(row["x0"]), float(row["y0"]), float(row["x1"]), float(row["y1"])])
        by_file[name]["labels"].append(phrase)
    if len(vocabulary) > MAX_PROMPTS:
        raise ValueError(f"boxes.csv uses {len(vocabulary)} phrases; at most MAX_PROMPTS ({MAX_PROMPTS}) are allowed")
    return list(by_file.values()), vocabulary


def write_dataset_csv(records: Sequence[Mapping[str, Any]], path: str | Path) -> Path:
    """A summary table (id, image size, box count, count per phrase, provenance), not the BYOD format."""
    out = Path(path)
    out.parent.mkdir(parents=True, exist_ok=True)
    phrases = sorted({label for r in records for label in r["labels"]})
    with open(out, "w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(["id", "width", "height", "n_boxes", *phrases, "source"])
        for r in records:
            writer.writerow([r["id"], r["image"].width, r["image"].height, len(r["boxes"]), *[r["labels"].count(p) for p in phrases], r.get("source", "")])
    return out
